draw(C--G--E--F--B--D--cycle);
draw(F--H);
draw(D--H);
draw(G--H);
draw(A--B,dashed);
draw(A--C,dashed);
draw(A--E,dashed);
draw(T--P--Q--S,dashed);
draw(S--R--T);

label("$(0,0,0)$", A, NE);
label("$(0,0,4)$", B, N);
label("$(0,4,0)$", C, dir(0));
